using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text;
using System.Runtime.Versioning;
using System.Web.Script.Serialization;
using System.Windows.Forms;
[assembly:TargetFramework(".NETFramework,Version=v4.8")]
class QueueUiTests {
 delegate bool EnumWindow(IntPtr w,IntPtr p);
 [DllImport("user32.dll")]static extern bool EnumThreadWindows(uint t,EnumWindow cb,IntPtr data);
 [DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr w,StringBuilder s,int n);
 [DllImport("user32.dll")]static extern IntPtr GetWindow(IntPtr w,uint command);
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr w,uint msg,IntPtr a,IntPtr b);
 static bool CloseAnswer(Form f,int answer){bool seen=false;using(var timer=new System.Windows.Forms.Timer()){timer.Interval=100;timer.Tick+=delegate{EnumThreadWindows(GetCurrentThreadId(),delegate(IntPtr w,IntPtr unused){var name=new StringBuilder(64);GetClassName(w,name,64);if(name.ToString()=="#32770"&&GetWindow(w,4)==f.Handle){seen=true;PostMessage(w,0x111,new IntPtr(answer),IntPtr.Zero);}return true;},IntPtr.Zero);};timer.Start();f.Close();timer.Stop();}return seen;}
 static Type type;static object Value(object o,string n){return type.GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Call(Form f,string name){type.GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,null);}
 static Form Form(string root){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"settings.json"),"{\"OutputFolder\":\""+Path.Combine(root,"audio").Replace("\\","\\\\")+"\",\"ScanFolder\":\"\"}");Form f=(Form)Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public,null,new object[]{root},null);f.ShowInTaskbar=false;f.Show();Application.DoEvents();return f;}
 static void Pump(Func<bool> done){Stopwatch time=Stopwatch.StartNew();while(!done()&&time.ElapsedMilliseconds<15000){Application.DoEvents();System.Threading.Thread.Sleep(15);}if(!done())throw new Exception("bounded mock timeout");}
 static List<string> States(Form f){var queue=Value(f,"queue");var items=(IEnumerable)queue.GetType().GetField("Items").GetValue(queue);var states=new List<string>();foreach(object item in items)states.Add((string)item.GetType().GetField("State").GetValue(item));return states;}
 static void Assert(bool yes,string name,Dictionary<string,object> results){results[name]=yes;if(!yes)throw new Exception(name);}
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);type=Assembly.LoadFrom(Path.GetFullPath(args[0])).GetType("MainWindow");string root=Path.GetFullPath(args[1]);if(Directory.Exists(root)&&Directory.GetFileSystemEntries(root).Length>0)throw new Exception("Test state directory must be new and empty; never use the app directory.");Directory.CreateDirectory(root);string python=Path.GetFullPath(args[2]),worker=Path.GetFullPath(args[3]);var result=new Dictionary<string,object>();Form current=null;try{
  string run=Path.Combine(root,"sequential");current=Form(run);File.WriteAllText(Path.Combine(run,"tool-config.json"),new JavaScriptSerializer().Serialize(new{python=python}));File.Copy(worker,Path.Combine(run,"backend.py"),true);type.GetField("sessionToken",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(current,"SYNTHETIC_LOGIN_FOR_MOCK_ONLY");TextBox link=(TextBox)Value(current,"link");link.Text="https://music.apple.com/us/song/1\nhttps://music.apple.com/us/song/2\nhttps://music.apple.com/us/song/3\nhttps://music.apple.com/us/song/1\nhttps://other.invalid/song/4";((Button)Value(current,"addQueue")).PerformClick();Assert(States(current).Count==3,"mixed input duplicates and invalid do not enqueue",result);Assert(((Button)Value(current,"cancel")).Enabled,"waiting queue can be cancelled before start",result);
  ((Button)Value(current,"download")).PerformClick();Process first=(Process)Value(current,"process");int id=first.Id;((Button)Value(current,"download")).PerformClick();Assert(((Process)Value(current,"process")).Id==id,"repeated click preserves single worker",result);
  link.Text="https://music.apple.com/us/song/4";((Button)Value(current,"addQueue")).PerformClick();Assert(States(current).Count==4,"can append while current worker active",result);
  bool sawPercent=false;Pump(delegate{Label pct=(Label)Value(current,"progressPercent");sawPercent|=pct.Text.Contains("25");return !(bool)Value(current,"queueRunning")&&Value(current,"process")==null;});var states=States(current);Assert(String.Join(",",states.ToArray())=="success,error,success,success","failed item continues through remaining items",result);Assert(sawPercent,"mock transfer percentage reaches GUI",result);Assert(Directory.GetDirectories(Path.Combine(run,"private","jobs")).Length==0,"per-item cookie and job directories cleaned",result);Assert(!File.Exists(Path.Combine(run,"concurrent-failure")),"mock workers never overlap",result);current.Close();current=null;
  run=Path.Combine(root,"cancel");current=Form(run);File.WriteAllText(Path.Combine(run,"tool-config.json"),new JavaScriptSerializer().Serialize(new{python=python}));File.Copy(worker,Path.Combine(run,"backend.py"),true);type.GetField("sessionToken",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(current,"SYNTHETIC_LOGIN_FOR_MOCK_ONLY");((TextBox)Value(current,"link")).Text="https://music.apple.com/us/song/9\nhttps://music.apple.com/us/song/10";((Button)Value(current,"download")).PerformClick();Call(current,"CancelQueue");Pump(delegate{return Value(current,"process")==null;});Assert(String.Join(",",States(current).ToArray())=="cancelled,cancelled","cancel current and waiting without next worker",result);Assert(Directory.GetDirectories(Path.Combine(run,"private","jobs")).Length==0,"cancel removes owned temporary cookies",result);current.Close();current=null;
  run=Path.Combine(root,"missing-auth");current=Form(run);((TextBox)Value(current,"link")).Text="https://music.apple.com/us/song/11";((Button)Value(current,"download")).PerformClick();((Button)Value(current,"download")).PerformClick();Assert(Value(current,"process")==null&&!(bool)Value(current,"queueRunning")&&States(current).Count==1,"missing auth remains responsive and retryable",result);Call(current,"CancelQueue");current.Close();current=null;

  run=Path.Combine(root,"invalid-vault");current=Form(run);Directory.CreateDirectory(Path.Combine(run,"private"));File.WriteAllText(Path.Combine(run,"private","login.dpapi"),"SYNTHETIC_INVALID_VAULT_ONLY");((TextBox)Value(current,"link")).Text="https://music.apple.com/us/song/12";((Button)Value(current,"download")).PerformClick();Application.DoEvents();Assert(Value(current,"process")==null&&!(bool)Value(current,"queueRunning"),"unreadable vault pauses without reschedule loop",result);Call(current,"CancelQueue");current.Close();current=null;
  run=Path.Combine(root,"close-waiting");current=Form(run);((TextBox)Value(current,"link")).Text="https://music.apple.com/us/song/13";((Button)Value(current,"addQueue")).PerformClick();bool dialog=CloseAnswer(current,7);Assert(dialog&&!current.IsDisposed&&States(current)[0]=="waiting","decline close preserves queued item",result);dialog=CloseAnswer(current,6);Assert(dialog&&current.IsDisposed,"confirm close disposes waiting queue",result);current=null;
  run=Path.Combine(root,"close-active");current=Form(run);File.WriteAllText(Path.Combine(run,"tool-config.json"),new JavaScriptSerializer().Serialize(new{python=python}));File.Copy(worker,Path.Combine(run,"backend.py"),true);type.GetField("sessionToken",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(current,"SYNTHETIC_LOGIN_FOR_MOCK_ONLY");((TextBox)Value(current,"link")).Text="https://music.apple.com/us/song/9\nhttps://music.apple.com/us/song/10";((Button)Value(current,"download")).PerformClick();dialog=CloseAnswer(current,6);Assert(dialog&&current.IsDisposed&&Directory.GetDirectories(Path.Combine(run,"private","jobs")).Length==0,"confirm close cancels own worker and cleans temporary cookies",result);current=null;
 }catch(Exception e){result["harness_failure"]=e.GetType().Name+":"+e.Message;Environment.ExitCode=1;}finally{if(current!=null){Call(current,"CancelQueue");Pump(delegate{return Value(current,"process")==null;});current.Close();}File.WriteAllText(Path.Combine(root,"queue-ui-results.json"),new JavaScriptSerializer().Serialize(result));}}
}
